package org.sigf.ui;

import javafx.concurrent.Task;
import javafx.scene.Node;
import javafx.scene.control.*;
import javafx.scene.layout.*;
import javafx.geometry.Pos;
import java.math.*;
import java.text.*;
import java.util.*;
import java.util.concurrent.Callable;
import java.util.function.*;
import org.sigf.domain.ReportGrid;

final class Views {
 private Views(){}
 static Label label(String text,String style){Label l=new Label(text);l.getStyleClass().add(style);l.setWrapText(true);return l;}
 static Button button(String text,Runnable action,boolean primary){Button b=new Button(text);b.setOnAction(e->action.run());if(primary)b.getStyleClass().add("primary");return b;}
 static Button button(String text,String icon,Runnable action,boolean primary){Button b=button(text,action,primary);b.setGraphic(UiIcons.icon(icon,"action-icon",20));return b;}
 static Label heading(String text,String style,String icon){Label l=label(text,style);l.setGraphic(UiIcons.icon(icon,"heading-icon"));return l;}
 static StackPane searchBox(TextField field,String icon){StackPane glyph=UiIcons.icon(icon,"search-icon",20);StackPane box=new StackPane(field,glyph);box.getStyleClass().add("search-box");StackPane.setAlignment(glyph,Pos.CENTER_LEFT);StackPane.setMargin(glyph,new javafx.geometry.Insets(0,0,0,11));return box;}
 static VBox cardWithIcon(String title,String icon,Node... children){VBox card=card(title,children);if(!title.isEmpty())((Label)card.getChildren().getFirst()).setGraphic(UiIcons.icon(icon,"heading-icon"));return card;}
 static HBox headerWithIcon(String title,String subtitle,String icon,Node... actions){HBox header=header(title,subtitle,actions);StackPane badge=new StackPane(UiIcons.icon(icon,"heading-icon",26));badge.setMinSize(44,44);badge.setPrefSize(44,44);badge.setMaxSize(44,44);badge.getStyleClass().add("module-icon");header.getChildren().addFirst(badge);return header;}
 static Button iconButton(String label,String icon,Runnable action){Button button=button("",action,false);button.setGraphic(UiIcons.icon(icon,"toolbar-icon"));button.setTooltip(new Tooltip(label));button.setAccessibleText(label);return button;}
 static VBox card(String heading,Node... children){VBox v=new VBox(12);v.getStyleClass().add("work-card");if(!heading.isEmpty()){Label title=label(heading,"panel-heading");title.setMaxWidth(Double.MAX_VALUE);v.getChildren().add(title);}v.getChildren().addAll(children);return v;}
 static HBox header(String title,String subtitle,Node... actions){Region spacer=new Region();HBox.setHgrow(spacer,Priority.ALWAYS);HBox h=new HBox(12,new VBox(4,label(title,"dashboard-title"),label(subtitle,"muted")),spacer);h.setAlignment(Pos.CENTER_LEFT);h.getChildren().addAll(actions);return h;}
 static String money(BigDecimal amount){return amount==null?"Sin clasificar":"C$ "+new DecimalFormat("#,##0.00",DecimalFormatSymbols.getInstance(Locale.US)).format(amount);}
 static <T> void column(TableView<T> table,String title,Function<T,?> value){TableColumn<T,Object> col=new TableColumn<>(title);col.setCellValueFactory(x->new javafx.beans.property.ReadOnlyObjectWrapper<>(value.apply(x.getValue())));col.setMinWidth(55);col.setPrefWidth(140);col.setCellFactory(c->new TableCell<>(){protected void updateItem(Object value,boolean empty){super.updateItem(value,empty);setText(empty||value==null?null:value.toString());setTooltip(empty||value==null?null:new Tooltip(value.toString()));}});table.getColumns().add(col);}
 static <T> TableView<T> table(String empty){TableView<T> table=new TableView<>();table.setPlaceholder(label(empty,"muted"));table.setColumnResizePolicy(TableView.CONSTRAINED_RESIZE_POLICY_ALL_COLUMNS);return table;}
 static String friendly(String raw){return switch(raw){case "SALE"->"Venta registrada";case "PURCHASE"->"Compra recibida";case "ADJUSTMENT"->"Ajuste de inventario";case "SALE_VOID"->"Venta anulada";case "CONFIRMED"->"Confirmada";case "VOID"->"Anulada";case "CASH"->"Efectivo";case "CARD"->"Tarjeta";case "TRANSFER"->"Transferencia";case "true"->"Sí";case "false"->"No";default->raw;};}
 static String value(String column,String raw){if(raw.isBlank())return "—";if(Set.of("total","subtotal","tax","base","iva","importe","costo","unit_cost","sale_price").contains(column))try{return money(new BigDecimal(raw));}catch(Exception ignored){}if(column.equals("tax_rate")||column.equals("tasa_iva"))try{return new BigDecimal(raw).multiply(new BigDecimal("100")).stripTrailingZeros().toPlainString()+" %";}catch(Exception ignored){}if(raw.matches("\\d{4}-\\d{2}-\\d{2}.*"))return raw.substring(8,10)+"/"+raw.substring(5,7)+"/"+raw.substring(0,4)+(raw.length()>15?" "+raw.substring(11,16):"");return friendly(raw);}
 static void grid(TableView<List<String>> table,ReportGrid data){table.getColumns().clear();for(int i=0;i<data.columns().size();i++){int n=i;String name=data.columns().get(i);String title=switch(name){case "id","referencia"->"N.º";case "created_at","fecha"->"Fecha";case "name"->"Nombre";case "tax"->"IVA";case "status"->"Estado";case "customer"->"Cliente";case "quantity"->"Cantidad";case "code","codigo"->"Código";case "sale_price"->"Precio sin IVA";case "tax_rate","tasa_iva"->"IVA";case "minimum_stock"->"Mínimo";case "expires_on"->"Vencimiento";case "blocked"->"Bloqueado";case "active"->"Activo";case "username"->"Usuario";case "role"->"Rol";case "vendible"->"Vendible";default->Character.toUpperCase(name.charAt(0))+name.substring(1).replace('_',' ');};column(table,title,x->value(name,x.get(n)));}double[] weights=data.columns().stream().mapToDouble(n->Set.of("name","producto","cliente","proveedor","details").contains(n)?3:Set.of("created_at","fecha","tipo","movimiento","estado","status").contains(n)?2:1.2).toArray();widths(table,weights);table.getItems().setAll(data.rows());}
 static <T> TableCell<T,String> editCell(){return new TableCell<>(){final TextField editor=new TextField();{editor.setOnAction(e->commitEdit(editor.getText()));editor.focusedProperty().addListener((o,a,b)->{if(!b&&isEditing())commitEdit(editor.getText());});}public void startEdit(){super.startEdit();if(!isEditing())return;editor.setText(getItem());setText(null);setGraphic(editor);editor.requestFocus();editor.selectAll();}public void cancelEdit(){super.cancelEdit();setGraphic(null);setText(getItem());}public void commitEdit(String value){super.commitEdit(value);setGraphic(null);setText(getItem());}protected void updateItem(String value,boolean empty){super.updateItem(value,empty);if(!isEditing()){setGraphic(null);setText(empty?null:value);}}};}
 static void widths(TableView<?> table,double... weights){if(weights.length!=table.getColumns().size())throw new IllegalArgumentException("Columnas inválidas");table.setColumnResizePolicy(TableView.UNCONSTRAINED_RESIZE_POLICY);double sum=java.util.Arrays.stream(weights).sum();for(int i=0;i<weights.length;i++){var column=table.getColumns().get(i);column.prefWidthProperty().bind(table.widthProperty().subtract(20).multiply(weights[i]/sum));}}
 static void date(DatePicker picker){picker.setConverter(new javafx.util.StringConverter<java.time.LocalDate>(){private final java.time.format.DateTimeFormatter format=java.time.format.DateTimeFormatter.ofPattern("dd/MM/uuuu").withResolverStyle(java.time.format.ResolverStyle.STRICT);public String toString(java.time.LocalDate date){return date==null?"":format.format(date);}public java.time.LocalDate fromString(String value){if(value==null||value.isBlank())return null;try{return java.time.LocalDate.parse(value,format);}catch(Exception ex){return java.time.LocalDate.parse(value);}}});picker.setPromptText("DD/MM/AAAA");picker.getEditor().setText(picker.getConverter().toString(picker.getValue()));}
 static void error(Throwable ex){new Alert(Alert.AlertType.ERROR,Objects.toString(ex.getMessage(),"No se pudo completar la operación"),ButtonType.OK).showAndWait();}
 static boolean confirm(String text){return new Alert(Alert.AlertType.CONFIRMATION,text,ButtonType.OK,ButtonType.CANCEL).showAndWait().orElse(ButtonType.CANCEL)==ButtonType.OK;}
 static <T> void async(Callable<T> job,Consumer<T> done,Consumer<Throwable> failed){Task<T> t=new Task<>(){protected T call()throws Exception{return job.call();}};t.setOnSucceeded(e->done.accept(t.getValue()));t.setOnFailed(e->failed.accept(t.getException()));Thread thread=new Thread(t,"sigf-view");thread.setDaemon(true);thread.start();}
 static void responsive(SplitPane split){split.widthProperty().addListener((o,a,b)->split.setOrientation(b.doubleValue()<950?javafx.geometry.Orientation.VERTICAL:javafx.geometry.Orientation.HORIZONTAL));}
}
